humanKnightBody:
is_available_quick = {
	ai = yes
	hostage = no
}
myv_is_wyvern = no
can_be_warrior_trigger = { ARMY_OWNER = $ARMY_OWNER$ }
trigger_if = { # Admin governors cannot be knights
	limit = {
		$ARMY_OWNER$ = { government_has_mechanic = administrative }
		is_courtier = no
		exists = primary_title
	}
	primary_title = {
		tier < tier_duchy
		trigger_if = {
			limit = { is_noble_family_title = yes }
			always = no
		}
	}
}
trigger_if = {
	limit = {
		$ARMY_OWNER$.culture = {
			has_cultural_parameter = minimum_prowess_for_knights
		}
	}
	prowess >= 12
}
trigger_if = {
	limit = {
		is_clergy = yes
	}
	OR = {
		rite = { rite_has_parameter = clergy_can_fight }
		AND = {
			has_personal_tenet_flag = clergy_can_fight_personal
			NOT = { rite = { rite_has_parameter = pacifist } }
		}
		culture = { has_cultural_parameter = culture_clergy_can_fight }
		AND = {
			$ARMY_OWNER$.culture = {
				has_cultural_parameter = high_prowess_ignores_knight_restrictions
			}
			prowess >= 10
		}
	}
}
OR = {
	AND = {
		$ARMY_OWNER$.culture = {
			has_cultural_parameter = high_prowess_ignores_knight_restrictions
		}
		prowess >= 10
	}
	has_trait = order_member
	NOR = {
		has_trait = blind
		has_court_position = master_assassin_court_position
	}
}
trigger_if = {
	limit = {
		exists = liege.diarch
	}
	this != liege.diarch
}
trigger_if = {
	limit = {
		$ARMY_OWNER$ = {
			is_ai = no
		}
	}
	is_knight_permitted = $ARMY_OWNER$
}

mountedDeploymentBody:
trigger_if = {
    limit = { myv_is_living_wyvern = yes exists = var:myv_war_mount_rider }
    var:myv_war_mount_rider = {
        myv_is_active_wyvern_war_rider = yes
        var:myv_war_mount = prev
        OR = {
            exists = commanding_army.location
            exists = knight_army.location
        }
    }
}
trigger_else = { always = no }

nativeTargetPower:
myv_wyvern_target_prowess = {
    value = myv_wyvern_size_prowess
    multiply = myv_wyvern_physique_prowess_multiplier
    multiply = myv_wyvern_temperament_prowess_multiplier
    multiply = myv_wyvern_wing_injury_prowess_multiplier
    multiply = myv_wyvern_hindleg_injury_prowess_multiplier
    multiply = myv_wyvern_tail_injury_prowess_multiplier
    if = {
        limit = { has_character_modifier = myv_wyvern_enraged }
        multiply = 1.1
    }
    if = {
        limit = { has_character_modifier = myv_wyvern_hungry }
        multiply = 0.9
    }
    multiply = myv_wyvern_malnutrition_prowess_multiplier
    round = yes
    min = 0
    max = 150
}

nativeMaintenance:
myv_wyvern_tamed_maintenance_effect = {
    if = {
        limit = {
            has_trait = myv_wyvern_tamed
            has_variable = myv_wyvern_bonded_character
            var:myv_wyvern_bonded_character = { is_alive = yes }
        }
        save_scope_as = myv_tamed_wyvern
        var:myv_wyvern_bonded_character = { save_scope_as = myv_wyvern_bonded_owner }
        myv_sync_wyvern_deployed_army_location_effect = yes

        if = {
            limit = {
                has_any_court_position = yes
                exists = employer
            }
            employer = {
                save_scope_as = myv_tamed_wyvern_employer
                add_character_flag = free_revoke_cost
            }
            fire_specific_court_position_effect = {
                CHARACTER = scope:myv_tamed_wyvern
                LIEGE = scope:myv_tamed_wyvern_employer
            }
        }

        if = {
            limit = {
                scope:myv_wyvern_bonded_owner = { is_landed = yes }
                OR = {
                    NOT = { exists = employer }
                    NOT = { employer = scope:myv_wyvern_bonded_owner }
                }
            }
            set_employer = scope:myv_wyvern_bonded_owner
        }
        else_if = {
            limit = {
                scope:myv_wyvern_bonded_owner = { exists = employer }
                OR = {
                    NOT = { exists = employer }
                    NOT = { employer = scope:myv_wyvern_bonded_owner.employer }
                }
            }
            set_employer = scope:myv_wyvern_bonded_owner.employer
        }

        # A travel companion remains beside its rider throughout the activity
        # between the outbound and return plans. Travel itself moves companions;
        # this repair only covers the stationary stay and old saves in which the
        # ordinary home pulse already sent the wyvern back to its lair.
        if = {
            limit = {
                has_character_flag = myv_wyvern_travelling_with_rider
                has_variable = myv_wyvern_travel_rider
                var:myv_wyvern_travel_rider = {
                    is_alive = yes
                    exists = location
                    exists = involved_activity
                }
                NOT = { exists = current_travel_plan }
                NOT = { location = var:myv_wyvern_travel_rider.location }
            }
            set_location = {
                location = var:myv_wyvern_travel_rider.location
                stick_to_location = yes
            }
        }

        if = {
            limit = {
                NOT = { has_character_flag = myv_wyvern_in_stable }
                NOT = { has_character_flag = myv_wyvern_travelling_with_rider }
            }

            # The lair follows the owner's realm capital, not the owner's
            # temporary travel or army position.
            if = {
                limit = {
                    scope:myv_wyvern_bonded_owner = {
                        is_landed = yes
                        exists = capital_province
                    }
                }
                set_variable = {
                    name = myv_wyvern_lair_barony
                    value = scope:myv_wyvern_bonded_owner.capital_province.barony
                }
            }
            else_if = {
                limit = {
                    scope:myv_wyvern_bonded_owner = {
                        exists = employer
                        employer = { exists = capital_province }
                    }
                }
                set_variable = {
                    name = myv_wyvern_lair_barony
                    value = scope:myv_wyvern_bonded_owner.employer.capital_province.barony
                }
            }
            else_if = {
                limit = { exists = scope:myv_wyvern_bonded_owner.location }
                set_variable = {
                    name = myv_wyvern_lair_barony
                    value = scope:myv_wyvern_bonded_owner.location.barony
                }
            }

            # While the bonded owner is personally serving in an army, the
            # army movement on_action owns the war mount's live location.
            if = {
                limit = {
                    has_variable = myv_wyvern_lair_barony
                    NOT = {
                        AND = {
                            has_variable = myv_war_mount_rider
                            var:myv_war_mount_rider = scope:myv_wyvern_bonded_owner
                            scope:myv_wyvern_bonded_owner = {
                                has_variable = myv_war_mount
                                var:myv_war_mount = scope:myv_tamed_wyvern
                                OR = {
                                    is_commanding_army = yes
                                    exists = knight_army
                                }
                            }
                        }
                    }
                }
                var:myv_wyvern_lair_barony = {
                    title_province = { save_scope_as = myv_tamed_wyvern_home }
                }
                if = {
                    limit = {
                        exists = scope:myv_tamed_wyvern_home
                        NOT = { location = scope:myv_tamed_wyvern_home }
                    }
                    set_location = {
                        location = scope:myv_tamed_wyvern_home
                        stick_to_location = yes
                    }
                }
            }
        }
        remove_character_flag = myv_wyvern_roaming
    }
}

nativeFollow:
myv_wyvern_follow_rider_army_effect = {
    save_scope_as = myv_following_wyvern_rider
    if = {
        limit = {
            has_variable = myv_war_mount
            var:myv_war_mount = {
                myv_is_living_wyvern = yes
                myv_is_wyvern_deployed_with_army = yes
                has_variable = myv_war_mount_rider
                var:myv_war_mount_rider = scope:myv_following_wyvern_rider
            }
            exists = scope:myv_war_mount_army_location
        }
        var:myv_war_mount = {
            if = {
                limit = { NOT = { location = scope:myv_war_mount_army_location } }
                set_location = {
                    location = scope:myv_war_mount_army_location
                    stick_to_location = yes
                }
            }
        }
    }
}

nativeLocationSync:
myv_sync_wyvern_deployed_army_location_effect = {
    clear_saved_scope = myv_deployed_wyvern_army_location
    if = {
        limit = { myv_is_wyvern_deployed_with_army = yes }
        var:myv_war_mount_rider = {
            if = {
                limit = { exists = commanding_army.location }
                commanding_army.location = { save_scope_as = myv_deployed_wyvern_army_location }
            }
            else_if = {
                limit = { exists = knight_army.location }
                knight_army.location = { save_scope_as = myv_deployed_wyvern_army_location }
            }
        }
        if = {
            limit = {
                exists = scope:myv_deployed_wyvern_army_location
                NOT = { location = scope:myv_deployed_wyvern_army_location }
            }
            set_location = {
                location = scope:myv_deployed_wyvern_army_location
                stick_to_location = yes
            }
        }
    }
    clear_saved_scope = myv_deployed_wyvern_army_location
}

nativeMountInteraction:
myv_set_wyvern_war_mount_interaction = {
	category = interaction_category_friendly
	filter_tags = { myv_wyvern_interaction }
	icon = icon_combat
	interface_priority = 98
	common_interaction = yes
	auto_accept = yes
	use_diplomatic_range = yes

	desc = myv_set_wyvern_war_mount_interaction_desc

	is_shown = {
		scope:actor = {
			is_ai = no
			is_alive = yes
			has_trait = myv_wyvern_rider
			NOT = { has_variable = myv_war_mount }
		}
		scope:recipient = {
			myv_is_living_wyvern = yes
			has_trait = myv_wyvern_harmony
			has_relation_myv_wyvern_bonded_character = scope:actor
			NOT = { has_variable = myv_war_mount_rider }
		}
	}

	is_valid_showing_failures_only = {
		scope:actor = {
			is_imprisoned = no
			is_incapable = no
		}
	}

	on_accept = {
		scope:recipient = {
			set_variable = { name = myv_war_mount_rider value = scope:actor }
		}
		scope:actor = {
			set_variable = { name = myv_war_mount value = scope:recipient }
			myv_refresh_war_mount_combat_stats_effect = yes
		}
	}
}

nativeAiAttempt:
myv_wyvern_ai_attempt_slay_effect = {
 clear_saved_scope = myv_slay_wyvern_target
 save_scope_as = myv_wyvern_ai_slay_hunter
 if = {
  limit = { myv_can_ai_attempt_wyvern_slay = yes has_global_variable_list = myv_living_wyverns }
  random = {
   chance = myv_wyvern_ai_slay_quarterly_chance
   random_in_global_list = {
    variable = myv_living_wyverns
    limit = { myv_is_living_wild_wyvern = yes in_diplomatic_range = scope:myv_wyvern_ai_slay_hunter }
    save_scope_as = myv_slay_wyvern_target
   }
   if = { limit = { exists = scope:myv_slay_wyvern_target } trigger_event = myv_wyvern_ai_slay.0001 }
  }
 }
 clear_saved_scope = myv_slay_wyvern_target
 clear_saved_scope = myv_wyvern_ai_slay_hunter
}
